package ncasa.expense.application.settlement;
import ncasa.expense.application.*;import ncasa.expense.application.port.out.*;import ncasa.expense.domain.*;
public final class ListSettlementsUseCase {private final SettlementRepository r;private final HouseholdExpenseAccessPort a;public ListSettlementsUseCase(SettlementRepository r,HouseholdExpenseAccessPort a){this.r=r;this.a=a;}public SettlementPage execute(ListSettlementsQuery q){if(q.page()<0||q.size()<1||q.size()>100)throw new IllegalArgumentException("Invalid pagination");if(q.from()!=null&&q.to()!=null&&q.from().isAfter(q.to()))throw new IllegalArgumentException("From date must not be after to date");var h=new HouseholdRef(q.householdId());var context=a.getContext(h,q.actorAccountId());var member=q.memberId()==null?null:new MemberRef(q.memberId());if(member!=null)context.requireMember(member);var result=r.findPage(h,q.from(),q.to(),q.status(),member,q.page(),q.size());int pages=result.totalElements()==0?0:(int)Math.ceil((double)result.totalElements()/q.size());return new SettlementPage(result.items().stream().map(SettlementView::from).toList(),q.page(),q.size(),result.totalElements(),pages);}}
